ازجة وماء"], ["استخلص نتيجة من مقارنة المغذيات المتوفرة عند من يتناول 4 وجبات منتظمة ومن يستغني عن الفطور.", "مع 4 وجبات تبقى كمية المغذيات في الدم مستقرة، أما عند الاستغناء عن الفطور فتنخفض كثيرا قبل الغداء ويحصل شعور بالتعب"]]}, {"n": 22, "m": 5, "i": "⚖️", "t": "احترام النوعية في الحاجيات الغذائية", "B": [["وظائف الأغذية البسيطة", ["ماء وأملاح معدنية: بناء ووظيفة", "غلوسيدات (نشويات، سكر): طاقة بالدرجة الأولى", "ليبيدات: طاقة (وقليل بناء)", "بروتيدات: بناء بالدرجة الأولى", "فيتامينات وأملاح: وظيفة (حماية ووساطة)"]], ["الألياف", ["الألياف النباتية (السليلوز) غير قابلة للهضم وتسهّل عبور الأغذية في الأمعاء"]], ["تركيب الأغذية", ["الحليب ومشتقاته: بروتيدات ودسم", "اللحوم والأسماك والبيض: بروتيدات ودسم", "خبز وحبوب وبطاطا: غلوسيدات (خبز 100 g: 55 g غلوسيدات)", "مواد دسمة: زبدة وزيت ≈ 3200–3700 kJ لكل 100 g"]], ["التنويع", ["لا يكفي غذاء واحد: يجب تنويع الأغذية لتغطية كل الوظائف"]]], "K": "لكل مغذٍّ دور خاص، لذلك يجب تنويع الأغذية: طاقة وبناء ووقاية.", "M": ["بروتيدات: بناء", "غلوسيدات وليبيدات: طاقة", "فيتامينات وأملاح: وظيفة ووقاية", "ألياف: تسهل العبور"], "X": "كل غذاء يعمل في مجال: الخبز للطاقة، اللحم والحليب للبناء، الفواكه والخضر للوقاية. الجسم يحتاج الجميع.", "EX": [["صنّف الأغذية: خبز، لحم، حليب، زيت، برتقال حسب دورها الأساسي.", "خبز: طاقة (غلوسيدات). لحم: بناء (بروتيدات). حليب: بناء وطاقة. زيت: طاقة (ليبيدات). برتقال: فيتامينات وأملاح (وظيفة ووقاية)"], ["لماذا نوصي بالفواكه والخضر رغم قلة طاقتها؟", "لغناها بالفيتامينات والأملاح المعدنية والألياف التي تحمي من الأمراض وتسهّل الهضم"]]}, {"n": 23, "m": 5, "i": "💧", "t": "احترام الكم: الماء والأملاح والصيغة GPL 421", "B": [["الماء", ["يشكل ثلثي كتلة الجسم تقريبا", "الحاجة اليومية حوالي 2.5 L منها 1.2 L ماء شروب", "مدخلات: مشروبات 1200 ml، أغذية 1000 ml، تفاعلات الأيض 350 ml", "مخرجات: بول 1500 ml، هواء الشهيق 900 ml، براز 100 ml، عرق 50 ml"]], ["الأيونات المعدنية", ["كبيرة الحاجة: صوديوم، بوتاسيوم، كلسيوم، فوسفات، حديد، مغنزيوم", "ضعيفة الحاجة: اليود، النحاس، الكوبالت، المنغنيز، الزنك"]], ["GPL = 421", ["G غلوسيدات 4، P بروتيدات 2، L ليبيدات 1", "يجب أن تتواجد في كل وجبة رئيسية (فطور، غداء، عشاء)"]], ["الفيتامينات", ["كميات قليلة لكنها ضرورية، تتوفر في الغذاء ونقصها يسبب أمراضا"]]], "K": "التغذية المتوازنة تحترم الكم: ماء كاف، أملاح، فيتامينات، ونسب G P L = 4 : 2 : 1.", "M": ["ماء ≈ 2.5 L في اليوم", "G : P : L = 4 : 2 : 1", "فيتامينات: قليلة وإلزامية"], "X": "لا يكفي أن نأكل أنواعا مختلفة، بل بكميات مناسبة: كثير من الغلوسيدات، قدر أقل من البروتيدات، وأقل شيء الدسم.", "EX": [["احسب حصيلة الماء اليومية من الجدول.", "المدخلات: 1200 + 1000 + 350 = 2550 ml. المخرجات: 1500 + 900 + 100 + 50 = 2550 ml. الحصيلة متوازنة"], ["ما الخطأ في التغذية الذي تسمح الصيغة GPL 421 بتفاديه؟", "الإفراط في صنف واحد (كالدسم أو السكريات) أو غياب أحد الأصناف الثلاثة، فهي تحافظ على نسب متوازنة بين الغلوسيدات والبروتيدات والليبيدات في كل وجبة"]]}, {"n": 24, "m": 5, "i": "📈", "t": "تغيرات صرف الطاقة", "B": [["حسب النشاط والجنس", ["رجل 65 kg: خفيف 11300، متوسط 12500، قوي 14600، شاق جدا 16700 kJ/24h", "امرأة 55 kg: 8400، 9200، 10900، 12300 kJ/24h"]], ["حسب السن والجنس", ["رضيع (0–1 سنة): 3380 kJ", "طفل 4–7 سنوات: 7650", "10–13: فتيات 9800 وفتيان 10850", "13–16: فتيات 10400 وفتيان 12100", "16–20: فتيات 9650 وفتيان 12850"]], ["العوامل", ["السن والجنس وشدة النشاط"]]], "K": "الحاجة إلى الطاقة تتغير حسب السن والجنس ونوع النشاط، فيجب أن يوافق الغذاء صرف الطاقة.", "M": ["نشاط أكبر ← صرف أكبر", "فتيان 13–16: 12100 ؛ فتيات: 10400 kJ/24h", "الغذاء حسب الصرف = توازن"], "X": "كلما تحركت أكثر أو كبرت أكثر احتجت طاقة أكثر. وضع راتبك حسب نشاطك.", "EX": [["تلميذ في الرابعة متوسط عمره 15 سنة. ما حاجته من الطاقة وكيف نقسّمها على الغلوسيدات والبروتيدات والليبيدات بالنسب 4 : 2 : 1 (كتلا)؟", "الحاجة حوالي 12100 kJ/24h (فتى 13–16 سنة). لكل وحدة كتلة: 4×16.7 + 2×16.7 + 1×37.7 = 137.9 kJ. الوحدة = 12100 ÷ 137.9 ≈ 87.7 g. غلوسيدات ≈ 351 g، بروتيدات ≈ 175 g، ليبيدات ≈ 88 g (تقريبية)"], ["لماذا تحتاج الأم الحامل أو الرياضي إلى غذاء أكثر؟", "لأن صرف الطاقة أكبر: نشاط شاق أو بناء جسم جديد، فيجب تعويضه حتى لا يختل التوازن الطاقوي"]]}, {"n": 25, "m": 5, "i": "✅", "t": "قواعد التغذية المتوازنة", "B": [["التعريف", ["التغذية المتوازنة: تلبي حاجات العضوية نوعا وكما: طاقة وبناء ووقاية"]], ["النوعية", ["تنويع الأغذية من كل الأصناف (غلوسيدات، بروتيدات، ليبيدات، ماء، أملاح، فيتامينات، ألياف)"]], ["الكم", ["ماء كاف (2.5 L يوميا)", "GPL = 421", "طاقة توافق الصرف"]], ["السلوك", ["وجبات منتظمة (4 في اليوم) وفطور صباحي", "تقليل السكر والملح والدسم", "نشاط بدني منتظم", "تجنب الأكل السريع"]], ["الأخطار", ["البدانة، داء السكري، أمراض القلب والشرايين، سوء التغذية"]]], "K": "التغذية المتوازنة تنويع في النوعية، واحترام للكمية، وانتظام في الوجبات.", "M": ["نوع + كم + انتظام", "تقليل السكر والدسم", "نشاط بدني", "ماء كاف"], "X": "كأنك تبني منزلا: تحتاج مواد مختلفة (نوعية)، بكميات صحيحة (كم)، في أوقات منتظمة (انتظام).", "EX": [["قدّم تعريفا للتوازن الغذائي واستخلص قواعد التغذية الصحية.", "التوازن الغذائي: تغطية الحاجات من الطاقة والبناء والوقاية بتنويع الأغذية ونسب مناسبة. القواعد: تنويع، وجبات منتظمة (فطور كل يوم)، كمية تناسب الصرف، تقليل السكر والدسم، شرب الماء، نشاط بدني"], ["لماذا ننصح بوجبة الفطور كل صباح؟", "بعد الصيام الليلي تنخفض المغذيات في الدم، فالفطور يعوّضها ويمنع التعب قبل الغداء"]]}];
ZAD_EOF
cat > lessons_4am_nat.js <<'ZAD_EOF'
/* دروس علوم الطبيعة والحياة للسنة الرابعة متوسط (دار القصبة). يُحمَّل بعد lessons.js و n4_data.js */
(function(){
  if(typeof LESSONS_DB==='undefined'||typeof N4_DATA==='undefined')return;
  var KEY='__KEY__';
  var SUB={'0':'₀','1':'₁','2':'₂','3':'₃','4':'₄','5':'₅','6':'₆','7':'₇','8':'₈','9':'₉','+':'₊','-':'₋','=':'₌','(':'₍',')':'₎','a':'ₐ','e':'ₑ','h':'ₕ','i':'ᵢ','j':'ⱼ','k':'ₖ','l':'ₗ','m':'ₘ','n':'ₙ','o':'ₒ','p':'ₚ','r':'ᵣ','s':'ₛ','t':'ₜ','u':'ᵤ','v':'ᵥ','x':'ₓ'};
  var SUP={'0':'⁰','1':'¹','2':'²','3':'³','4':'⁴','5':'⁵','6':'⁶','7':'⁷','8':'⁸','9':'⁹','+':'⁺','-':'⁻','=':'⁼','(':'⁽',')':'⁾','n':'ⁿ','i':'ⁱ','k':'ᵏ','p':'ᵖ','a':'ᵃ','m':'ᵐ'};
  function conv(s,map,pre){var o='';for(var i=0;i<s.length;i++){if(!map[s[i]])return pre+'('+s+')';o+=map[s[i]]}return o}
  function fx(s){
    return String(s).replace(/`/g,'').replace(/_\{([^}]*)\}/g,function(m,a){return conv(a,SUB,'_')}).replace(/\^\{([^}]*)\}/g,function(m,a){return conv(a,SUP,'^')});
  }
  function text(c){
    var t=[];
    c.B.forEach(function(b){t.push('▸ '+fx(b[0]));b[1].forEach(function(x){t.push('• '+fx(x))})});
    t.push('▸ للحفظ');t.push('• '+fx(c.K));
    t.push('▸ طرق وقواعد');c.M.forEach(function(x){t.push('• '+fx(x))});
    t.push('▸ شرح مبسط');t.push('• '+fx(c.X));
    t.push('▸ تمارين محلولة');
    c.EX.forEach(function(e,j){t.push('• تمرين '+(j+1)+': '+fx(e[0]));t.push('• الحل: '+fx(e[1]))});
    t.push('▸ المرجع');t.push('• كتاب علوم الطبيعة والحياة للسنة الرابعة متوسط (دار القصبة) — الدرس '+c.m+': '+(N4_MQ[c.m]||'')+' — ملخص بتصرف');
    return t.join('\n');
  }
  var L=N4_DATA.map(function(c){var k=c.n<10?'0'+c.n:''+c.n;return {title:k+'. '+fx(c.t),content:text(c)}});
  var A=LESSONS_DB['4AM']=LESSONS_DB['4AM']||{};
  var o=A[KEY]||{};
  o.name=o.name||'علوم الطبيعة والحياة';
  o.lessons=L;
  o.maps='n4';
  A[KEY]=o;
})();
ZAD_EOF
